    pub fn maybe_ignore_above(mut self, value: Option<i32>) -> Self {
        self.ignore_above = value;
        self
    }

    pub fn dynamic(mut self, value: impl Into<DynamicMapping>) -> Self {
        self.dynamic = Some(value.into());
        self
    }

    /// Sets [`dynamic`](Self::dynamic) if `value` is `Some`.
    pub fn maybe_dynamic(mut self, value: Option<DynamicMapping>) -> Self {
        self.dynamic = value;
        self
    }

    pub fn fields(
        mut self,
        value: impl Into<indexmap::IndexMap<crate::typed::_types::PropertyName, Property>>,
    ) -> Self {
        self.fields = Some(value.into());
        self
    }

    /// Sets [`fields`](Self::fields) if `value` is `Some`.
    pub fn maybe_fields(
        mut self,
        value: Option<indexmap::IndexMap<crate::typed::_types::PropertyName, Property>>,
    ) -> Self {
        self.fields = value;
        self
    }

    /// Adds an entry to [`fields`](Self::fields).
    pub fn add_fields(
        mut self,
        key: impl Into<crate::typed::_types::PropertyName>,
        value: impl Into<Property>,
    ) -> Self {
        self.fields
            .get_or_insert_with(Default::default)
            .insert(key.into(), value.into());
        self
    }

    /// Adds an entry to [`fields`](Self::fields), with a builder.
    pub fn add_fields_with<B: crate::typed::builder::Build<Output = Property>>(
        self,
        key: impl Into<crate::typed::_types::PropertyName>,
        f: impl FnOnce(PropertyBuilder) -> B,
    ) -> Self {
        self.add_fields(key, f(PropertyBuilder::new()).build())
    }

